import{_ as a,o as l,c as o,a8 as d}from"./chunks/framework.CiGKN4gy.js";const _=JSON.parse('{"title":"内置变量","description":"","frontmatter":{"title":"内置变量","lang":"zh-CN"},"headers":[],"relativePath":"zh-cn/advance/variable.md","filePath":"zh-cn/advance/variable.md","lastUpdated":1790354326000}'),c={name:"zh-cn/advance/variable.md"};function i(t,e,r,n,s,f){return l(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjIlRTUlODYlODUlRTclQkQlQUUlRTUlOEYlOTglRTklODclOEYlMjIlMkMlMjJsYW5nJTIyJTNBJTIyemgtQ04lMjIlMkMlMjJkYXRlJTIyJTNBMTc5MDM1NDMyNjAwMCU3RA=="},[...e[0]||(e[0]=[d('<h1 id="内置变量" tabindex="-1">内置变量 <a class="header-anchor" href="#内置变量" aria-label="Permalink to &quot;内置变量&quot;">​</a></h1><p>在书写 nginx.conf 文件的时候不可避免地需要用到一些变量，如<code>$remote_addr</code>可以用来获取客户端 IP 地址。</p><p>本模块增加了多个可用的变量。</p><div class="warning custom-block"><p class="custom-block-title">不能和指令 <code>if</code> 共用</p><p>详见<a href="/ngx_waf-docs/zh-cn/guide/faq.html#模块的内置变量与指令-if">常见问题与解答</a>。</p></div><h2 id="waf-log" tabindex="-1"><code>$waf_log</code> <a class="header-anchor" href="#waf-log" aria-label="Permalink to &quot;`$waf_log`&quot;">​</a></h2><p>如果本次请求中防火墙进行了检查则不为空字符串，反之为空字符串。本变量主要用于 <code>access_log</code> 指令，详见 <a href="./log.html#自定义日志格式">自定义日志格式</a>。</p><h2 id="waf-blocking-log" tabindex="-1"><code>$waf_blocking_log</code> <a class="header-anchor" href="#waf-blocking-log" aria-label="Permalink to &quot;`$waf_blocking_log`&quot;">​</a></h2><p>如果本次请求本被模块拦截则不为空字符串，反之则为空字符串。本变量主要用于 <code>access_log</code> 指令，详见 <a href="./log.html#自定义日志格式">自定义日志格式</a>。</p><h2 id="waf-blocked" tabindex="-1"><code>$waf_blocked</code> <a class="header-anchor" href="#waf-blocked" aria-label="Permalink to &quot;`$waf_blocked`&quot;">​</a></h2><p>表示本次请求是否被本模块拦截，如果拦截了则其的值为<code>&#39;true&#39;</code>,反之则为<code>&#39;false&#39;</code>。</p><h2 id="waf-spend" tabindex="-1"><code>$waf_spend</code> <a class="header-anchor" href="#waf-spend" aria-label="Permalink to &quot;`$waf_spend`&quot;">​</a></h2><p>表示本次检查花费了多少时间（毫秒），保留 5 位小数，舍入规则取决于具体 C 标准库的实现。</p><h2 id="waf-rule-type" tabindex="-1"><code>$waf_rule_type</code> <a class="header-anchor" href="#waf-rule-type" aria-label="Permalink to &quot;`$waf_rule_type`&quot;">​</a></h2><p>如果本次请求命中黑白名单规则，则其值为触发的规则类型。下面是可能的取值。若没有命中黑白名单规则则其值为<code>&#39;&#39;</code>。</p><ul><li><code>&#39;CC-DENY&#39;</code></li><li><code>&#39;WHITE-IPV4&#39;</code></li><li><code>&#39;WHITE-IPV6&#39;</code></li><li><code>&#39;BLACK-IPV4&#39;</code></li><li><code>&#39;BLACK-IPV6&#39;</code></li><li><code>&#39;WHITE-URL&#39;</code></li><li><code>&#39;BLACK-URL&#39;</code></li><li><code>&#39;BLACK-ARGS&#39;</code></li><li><code>&#39;BLACK-USER-AGENT&#39;</code></li><li><code>&#39;WHITE-REFERER&#39;</code></li><li><code>&#39;BLACK-REFERER&#39;</code></li><li><code>&#39;BLACK-COOKIE&#39;</code></li><li><code>&#39;BLACK-POST&#39;</code></li><li><code>&#39;UNDER-ATTACK&#39;</code></li><li><code>&#39;FAKE-BOT&#39;</code></li><li><code>&#39;CAPTCHA&#39;</code></li></ul><h2 id="waf-rule-details" tabindex="-1"><code>$waf_rule_details</code> <a class="header-anchor" href="#waf-rule-details" aria-label="Permalink to &quot;`$waf_rule_details`&quot;">​</a></h2><p>如果本次请求被本模块拦截，则其值为触发的具体的规则的内容。若没有生效则其值为<code>&#39;&#39;</code>。</p><h2 id="waf-rate" tabindex="-1"><code>$waf_rate</code> <a class="header-anchor" href="#waf-rate" aria-label="Permalink to &quot;`$waf_rate`&quot;">​</a></h2><p>一个整数，表示一个统计周期内当前 IP 的访问次数。</p>',19)])])}const p=a(c,[["render",i]]);export{_ as __pageData,p as default};
